function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Count the nodes the level-order list describes: each node owns the next two slots.
  let nodes = 1;
  let slot = 1;
  for (let q = 0; q < nodes && slot < root.length; q++) {
    for (let side = 0; side < 2 && slot < root.length; side++, slot++) {
      if (root[slot] !== null) nodes++;
    }
  }
  if (slot < root.length) return 'Some values have no parent in the level-order list.';
  if (nodes > 10000) return 'The tree has at most 10^4 nodes.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < -2147483648 || v > 2147483647))) return 'Node values are 32-bit integers.';
  return null;
}

