function averageOfLevels(root) {
  // Depth-first: add each value to the running total and count of its depth, then divide at the end.
  const sums = [];
  const counts = [];
  const walk = (node, depth) => {
    if (!node) return;
    if (sums.length === depth) { sums.push(0); counts.push(0); }
    sums[depth] += node.val;
    counts[depth] += 1;
    walk(node.left, depth + 1);
    walk(node.right, depth + 1);
  };
  walk(root, 0);
  return sums.map((total, depth) => total / counts[depth]);
}

